select
  sum(f.[Exercised Qty]) as futu_exercised_qty,
  max(c.gyre_2023_china_subplan_total) - sum(f.[Exercised Qty]) as bci_shares_held_by_futu
from (
  select * from {futu}
  where trim(concat('', coalesce([Employee No.], ''))) <> ''
    and trim(concat('', coalesce([Employee No.], ''))) <> '员工编号'
) f, {control_metrics} c
